%[text] ## 
clear
close all
clc
format compact
format long g
set(groot,'DefaultAxesFontSize',14,'DefaultTextFontSize',14, ...
    'DefaultLegendFontSize',11,'DefaultColorbarFontSize',14);
%[text] ## **Set up the model using known independent variables and coefficients**
%[text] $f(x)=a\_0+a\_1x+a\_2x^2,$
%%\ Define Coefficients
a0 = 0 %[control:slider:9eca]{"position":[6,7]} %[output:3f8eaf7d]
a1 = 0 %[control:slider:58c1]{"position":[6,7]} %[output:2abdfab2]
a2 = 1 %[control:slider:0fd9]{"position":[6,7]} %[output:40809b0d]
xx =   -1:.1:1 ;
ff = a0 + a1.*xx + a2.*xx.^2 ;
% Plot the results
figure; %[output:670d34d2]
plot(xx, ff,'xr') ; %[output:670d34d2]
xlabel('x'); %[output:670d34d2]
ylabel('y'); %[output:670d34d2]
ylim([-1 1]) %[output:670d34d2]
title('Quadratic Function Plot'); %[output:670d34d2]
grid on; %[output:670d34d2]
%[text] 
%[text] ## **Fit to the data**
%[text] Put the independent variables in a matrix  $\\mathbf{M}=\n \\left\[\\begin{array}{ccc}\n 1 & x\_1 & x\_1^2 \\\\\n 1 & x\_2 & x\_2^2\\\\\n \\vdots & \\vdots & \\vdots \\\\\n 1 & x\_N & x\_N^2 \n \\end{array}\\right\]$,  
%[text] let $\\mathbf{a}=\n \\left\[\\begin{array}{cccc}\n a\_0\\\\a\_1\\\\a\_2\\\\\n \\end{array}\\right\].$  and $\\mathbf{f}=\n \\left\[\\begin{array}{cccc}\n f\_0\\\\f\_1\\\\f\_2\\\\\n \\vdots \\\\\n f\_N\n \\end{array}\\right\]\n \\end{array}\\right\].$ 
%[text] then $\\mathbf{f}=\\mathbf{M}\\mathbf{a}$. 
%[text] Fit to the data by inverting the matrix equation .... 
% Turn xx and ff into column vectors

x_col = xx';
f_col = ff';

% Insert code here -- define the measurement matrix with one line of code
M =  x_col.^[0 1 2];

% Estimate the coefficients a 

a_measured =  M\f_col ;
%[text] Now use the coefficients to calculate the fitted curve using a new measurement matrix that has many more points. 
%[text] $\\mathbf{f}=\\mathbf{M}\\mathbf{a}$.
xf = linspace (-1,1,201)';
M_fit = xf.^[0 1 2];
f_fit = a_measured(1) + a_measured(2).*xf + a_measured(3).*xf.^2 ;
% Plot the results
hold on %[output:670d34d2]
figure(2); %[output:0056b127]
plot(xx, ff,'xr'); hold on %[output:0056b127]
plot(xf,f_fit,'-r','LineWidth',2); %[output:0056b127]
xlabel('x'); %[output:0056b127]
ylabel('y'); %[output:0056b127]
ylim([-1 1]); %[output:0056b127]
title('Quadratic Function Plot'); %[output:0056b127]
grid on; %[output:0056b127]

%[text] 
%[text] 
%[text] Add some Gaussian random noise using the randn function.  
noise_level =  .1    ;
f_col = f_col + noise_level.*randn(size(f_col));
a_noisy =  M\f_col;
f_fit =   a_noisy(1) +  a_noisy(2).*xf + a_noisy(3).*xf.^2;  
%plot the results
figure(2);
plot(xx, f_col,'xr'); hold on %[output:0056b127]
plot(xf,f_fit,'-b','LineWidth',2); %[output:0056b127]
xlabel('x'); %[output:0056b127]
ylabel('y'); %[output:0056b127]
ylim([-1 1]); %[output:0056b127]
title('Quadratic Function Plot'); %[output:0056b127]
grid on; %[output:0056b127]




